//! BQ044 WIP: actual personal sacrifice observation and paid optional trigger.
//! Core invocation is not yet wired; public and internal complete admission remain closed.
use crate::{catalog,engine::RuleResult,model::*,rules::*,black_next20::BlackDeathObservation};
use std::collections::BTreeSet;
pub(crate) const ID:&str="BQ044";
pub(crate) const KEY:&str="bq044-personal-sacrifice";
fn same<T:serde::Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
pub(crate) fn definition()->Definition{with_abilities(vec![ability(KEY,"牺牲角色后可支付3（每失控减1）：一名敌方玩家牺牲角色或附属",Timing::Fast,vec![Cost::Assets(3)],vec![],vec![Op::BQ044Sacrifice{observation:None,discount:None}],Some(Event::BQ044Sacrifice))])}
fn owned(ops:&[Op])->bool{ops.iter().any(|o|match o{Op::BQ044Sacrifice{..}=>true,Op::ForEachLivingPlayer(v)|Op::ForEachLivingPlayerFromActor(v)=>owned(v),Op::IfTargetExhausted{exhausted,ready,..}=>owned(std::slice::from_ref(exhausted))||owned(std::slice::from_ref(ready)),_=>false})}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("bq044-")||a.event==Some(Event::BQ044Sacrifice)||owned(&a.ops)||a.modes.iter().any(|m|owned(&m.ops))}
fn frame_related(f:&ResolutionFrame)->bool{f.ability_key.starts_with("bq044-")||f.steps.iter().any(|s|owned(std::slice::from_ref(&s.op)))}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{let mut e=definition().abilities.remove(0);if let [Op::BQ044Sacrifice{observation,discount}]=a.ops.as_slice(){if discount.is_some_and(|n|n>3){return Err("BQ044折扣不能超过原费用".into());}e.ops=a.ops.clone();e.costs=vec![Cost::Assets(3-discount.unwrap_or(0))];if observation.is_none()&&discount.is_some(){return Err("BQ044折扣缺少实际牺牲事件".into());}}if id!=ID||!same(a,&e){return Err("BQ044原触发、个人费用或敌方目标被改写".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("BQ044印刷定义不可改写或移植".into());}Ok(())}
pub(crate) fn validate_choice(p:&Pending,a:&Action)->RuleResult<()>{let ours=match &p.resolution{ChoiceResolution::Declare{declaration,..}=>related(&declaration.ability),ChoiceResolution::Frame{frame,choice}=>frame_related(frame)||matches!(choice,FrameChoice::BQ044Enemy|FrameChoice::BQ044Sacrifice{..}),_=>false};if ours&&*a!=(Action{choice_id:a.choice_id.clone(),selected:a.selected.clone(),..Action::new("choose")}){return Err("BQ044选择不能夹带额外载荷".into());}Ok(())}
impl Game{
 pub(crate) fn bq044_sources(&self)->Vec<SourceSnapshot>{self.regions.iter().enumerate().filter(|(_,r)|!r.vacant).flat_map(|(r,v)|v.cards.iter().map(move|c|(r,c))).filter(|(_,c)|c.definition==ID&&!c.face_down&&!self.players[c.controller].eliminated).map(|(r,c)|self.source_snapshot(c,Some(r))).collect()}
 pub(crate) fn bq044_observe(&mut self,sources:&[SourceSnapshot],o:&BlackDeathObservation){for source in sources{if source.card.controller!=o.dead.controller{continue}let mut a=definition().abilities.remove(0);a.ops=vec![Op::BQ044Sacrifice{observation:Some(o.clone()),discount:None}];self.effects.push_back(Effect::Declare{declaration:Declaration{actor:source.card.controller,source:source.clone(),ability:a}});}}
 pub(crate) fn bq044_prepare(&self,d:&mut Declaration)->RuleResult<()>{if !related(&d.ability){return Ok(())}self.validate_bq044_declaration(d)?;if let [Op::BQ044Sacrifice{discount,..}]=d.ability.ops.as_mut_slice(){if discount.is_none(){let n=self.players[d.actor].society_zone.loss_control.min(3);*discount=Some(n);d.ability.costs=vec![Cost::Assets(3-n)];}}Ok(())}
 fn bq044_source(&self,actor:usize,s:&SourceSnapshot)->RuleResult<()>{let c=&s.card;if actor>=self.players.len()||c.controller!=actor||c.owner>=self.players.len()||c.definition!=ID||c.face_down||!self.mystic_instance_valid(&c.id)||s.region.is_none_or(|r|r>=self.regions.len())||s.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some(){return Err("BQ044触发缺少原明置个人来源".into());}self.mobility_immutable_identity(c)}
 fn bq044_observation<'a>(&self,actor:usize,ops:&'a[Op])->RuleResult<(&'a BlackDeathObservation,Option<u32>)>{let [Op::BQ044Sacrifice{observation:Some(o),discount}]=ops else{return Err("BQ044缺实际牺牲观察".into())};let c=&o.dead;if o.turn!=self.turn||c.controller!=actor||c.owner>=self.players.len()||c.face_down||catalog::card(&c.definition).kind!="character"||!self.mystic_instance_valid(&c.id)||!self.mystic_instance_number(&o.event_id).zip(self.mystic_instance_number(&c.id)).is_some_and(|(a,b)|a>b)||o.region>=self.regions.len()||!self.mystic_instance_valid(&o.region_instance)||discount.is_some_and(|n|n>3){return Err("BQ044个人牺牲观察身份损坏".into());}self.mobility_immutable_identity(c)?;Ok((o,*discount))}
 pub(crate) fn validate_bq044_declaration(&self,d:&Declaration)->RuleResult<()>{if !related(&d.ability){return Ok(())}validate_ability(&d.source.card.definition,&d.ability)?;self.bq044_source(d.actor,&d.source)?;let(_,n)=self.bq044_observation(d.actor,&d.ability.ops)?;if n.is_some_and(|n|n!=self.players[d.actor].society_zone.loss_control.min(3)){return Err("BQ044声明折扣不符当前本人秘社".into());}Ok(())}
 pub(crate) fn validate_bq044_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !frame_related(f){return Ok(())}self.bq044_source(f.actor,&f.source)?;let ops=f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>();let(_,discount)=self.bq044_observation(f.actor,&ops)?;let n=discount.ok_or("BQ044付费帧缺少实际折扣")?;self.validate_resource_frame(f)?;if f.ability_key!=KEY||f.cursor>1||!self.mystic_instance_number(&f.frame_id).zip(self.mystic_instance_number(&f.source.card.id)).is_some_and(|(a,b)|a>b)||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted)||f.steps[0].context!=f.actor||f.chosen_region.is_some(){return Err("BQ044原帧程序或阶段损坏".into());}let [PaidCost::Assets(ids)]=f.already_paid.as_slice()else{return Err("BQ044必须保留真实支付回执".into())};if f.money_units(0)!=(3-n) as usize||ids.iter().collect::<BTreeSet<_>>().len()!=ids.len()||ids.iter().any(|id|!self.mystic_instance_valid(id)){return Err("BQ044支付数额不符原折扣".into());}if !f.targets.is_empty(){return Err("BQ044卡文未指定目标，不能增加目标合同".into());}Ok(())}
 fn bq044_options(&self,seat:usize)->Vec<ChoiceOption>{if self.players[seat].eliminated{return vec![]}let mut v=self.regions.iter().enumerate().filter(|(_,r)|!r.vacant).flat_map(|(r,v)|v.cards.iter().map(move|c|(r,c))).filter(|(_,c)|c.controller==seat&&!c.face_down&&catalog::card(&c.definition).kind=="character").map(|(r,c)|self.option(c,seat,Some(r),None)).collect::<Vec<_>>();v.extend(self.attachments.iter().filter(|a|a.card.controller==seat&&!a.card.face_down&&self.attachment_host_valid(a)&&catalog::has_kind(catalog::card(&a.card.definition),"attachment")).map(|a|self.option(&a.card,seat,self.attachment_region(a),None)));v}
 fn bq044_enemies(&self,actor:usize)->Vec<ChoiceOption>{self.players.iter().filter(|p|!p.eliminated&&self.team(p.seat)!=self.team(actor)).map(|p|ChoiceOption{id:player_id(p.seat),label:p.name.clone(),card:None}).collect()}
 pub(crate) fn bq044_sacrifice(&mut self,f:ResolutionFrame)->RuleResult<()>{self.validate_bq044_frame(&f)?;let options=self.bq044_enemies(f.actor);if !options.is_empty(){self.choice(f.actor,"bq044-enemy","选择一名敌方玩家（非指定目标）".into(),options,1,1,None,ChoiceResolution::Frame{frame:Box::new(f),choice:FrameChoice::BQ044Enemy});}Ok(())}
 pub(crate) fn bq044_enemy_choose(&mut self,f:ResolutionFrame,chooser:usize,ids:&[String])->RuleResult<()>{self.validate_bq044_frame(&f)?;if f.cursor!=1||chooser!=f.actor||ids.len()!=1||!self.bq044_enemies(f.actor).iter().any(|o|o.id==ids[0]){return Err("BQ044须选择当前一名敌方玩家".into())}let seat=ids[0][1..].parse::<usize>().map_err(|_|"敌方玩家无效")?;let options=self.bq044_options(seat);if !options.is_empty(){self.choice(seat,"bq044-sacrifice","选择本人操控的一个角色或附属牺牲".into(),options,1,1,None,ChoiceResolution::Frame{frame:Box::new(f),choice:FrameChoice::BQ044Sacrifice{seat}});}Ok(())}
 pub(crate) fn bq044_finish(&mut self,f:ResolutionFrame,seat:usize,chooser:usize,ids:&[String])->RuleResult<()>{self.validate_bq044_frame(&f)?;if f.cursor!=1||chooser!=seat||seat>=self.players.len()||self.team(seat)==self.team(f.actor)||ids.len()!=1||!self.bq044_options(seat).iter().any(|o|o.id==ids[0]){return Err("BQ044只能牺牲原敌方玩家当前合法角色或附属".into());}self.remove_dead(&ids[0],RemovalCause::Sacrifice);Ok(())}
 pub(crate) fn validate_bq044_state(&self)->RuleResult<()>{let mut seen=BTreeSet::new();let mut remember=|s:&SourceSnapshot,ops:&[Op]|->RuleResult<()>{let(o,_)=self.bq044_observation(s.card.controller,ops)?;if !seen.insert((s.card.id.clone(),o.event_id.clone())){return Err("BQ044同次观察不得重复消费".into())}Ok(())};
 for i in &self.stack{if let Some(f)=&i.frame{if frame_related(f){self.validate_bq044_frame(f)?;remember(&f.source,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>())?;if i.id!=f.frame_id||i.controller!=f.actor||i.card.is_some()||i.reveal||i.deploy_region.is_some()||i.target!=f.targets.first().map(|t|t.id.clone())||f.cursor!=0{return Err("BQ044响应外壳损坏".into());}}}}
 for e in &self.effects{match e{Effect::Declare{declaration:d}if related(&d.ability)=>{self.validate_bq044_declaration(d)?;remember(&d.source,&d.ability.ops)?;},Effect::Frame{frame}if frame_related(frame)=>return Err("BQ044没有独立执行续体".into()),_=>()}}
 if let Some(p)=&self.pending{let expected=match &p.resolution{ChoiceResolution::Declare{declaration:d,stage}if related(&d.ability)=>{self.validate_bq044_declaration(d)?;remember(&d.source,&d.ability.ops)?;if !matches!(stage,DeclareChoice::Accept)||!matches!(d.ability.ops.as_slice(),[Op::BQ044Sacrifice{discount:Some(_),..}]){return Err("BQ044待声明须冻结折扣并选择敌方".into())}Some((d.actor,"trigger",format!("{}：{}",crate::batch3_trap::source_label(&d.source),d.ability.label),0,vec![ChoiceOption{id:"accept".into(),label:"发动触发能力".into(),card:None}]))},ChoiceResolution::Frame{frame:f,choice}if frame_related(f)||matches!(choice,FrameChoice::BQ044Enemy|FrameChoice::BQ044Sacrifice{..})=>{self.validate_bq044_frame(f)?;remember(&f.source,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>())?;if f.cursor!=1{return Err("BQ044牺牲阶段不符".into())}match choice{FrameChoice::BQ044Enemy=>Some((f.actor,"bq044-enemy","选择一名敌方玩家（非指定目标）".into(),1,self.bq044_enemies(f.actor))),FrameChoice::BQ044Sacrifice{seat}if *seat<self.players.len()&&self.team(*seat)!=self.team(f.actor)=>Some((*seat,"bq044-sacrifice","选择本人操控的一个角色或附属牺牲".into(),1,self.bq044_options(*seat))),_=>return Err("BQ044原敌方选择阶段损坏".into())}},_=>None};if let Some((seat,kind,title,min,options))=expected{let e=Choice{id:p.choice.id.clone(),kind:kind.into(),title,description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(seat),options,preview_cards:vec![],min:Some(min),max:Some(1),amount:None,allow_decline:Some(min==0)};if p.seat!=seat||e.options.is_empty()||!self.mystic_instance_valid(&p.choice.id)||!same(&p.choice,&e){return Err("BQ044待选合同、范围或席位被改写".into());}}}Ok(())}
}
